from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}
METHODS = ("card", "transfer")


def _receipt(member: dict, payment: dict, outcome: str, fee: int) -> str:
    """Format the outcome receipt the same way for every status."""
    return f"{payment['method']}:{member['id']}:{outcome}:{fee}"


def _verification_error(member: dict, payment: dict) -> str | None:
    """Return a shared validation failure for a recognized status, else None."""
    if member["tier"] not in TIER_FEES:
        return "unknown tier"
    if member["status"] == "lapsed":
        if not isinstance(member["expired_days"], int) or member["expired_days"] < 0:
            return "bad expiry"
    elif member["status"] == "suspended":
        if not isinstance(member["strikes"], int) or member["strikes"] < 0:
            return "bad strikes"
        if member["strikes"] >= MAX_STRIKES:
            return "too many strikes"
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in METHODS:
        return "unsupported method"
    return None


def _renew_active(member: dict, payment: dict) -> dict:
    fee = TIER_FEES[member["tier"]]
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return {"ok": True, "status": "renewed", "fee": fee,
            "receipt": _receipt(member, payment, "renewed", fee)}


def _renew_lapsed(member: dict, payment: dict) -> dict:
    if member["expired_days"] <= GRACE_DAYS:
        outcome, surcharge = "renewed", LATE_FEE
    else:
        outcome, surcharge = "reinstated", REINSTATE_SURCHARGE
    fee = TIER_FEES[member["tier"]] + surcharge
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return {"ok": True, "status": outcome, "fee": fee,
            "receipt": _receipt(member, payment, outcome, fee)}


def _renew_suspended(member: dict, payment: dict) -> dict:
    base = TIER_FEES[member["tier"]]
    fee = base + base // 2
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return {"ok": True, "status": "reactivated", "fee": fee,
            "receipt": _receipt(member, payment, "reactivated", fee)}


POLICIES = {
    "active": _renew_active,
    "lapsed": _renew_lapsed,
    "suspended": _renew_suspended,
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member, payment = raw_member, raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or not member["id"]:
        return {"ok": False, "error": "bad member id"}
    if member["status"] == "banned":
        return {"ok": False, "error": "member banned"}
    policy = POLICIES.get(member["status"])
    if policy is None:
        return {"ok": False, "error": "unknown status"}
    error = _verification_error(member, payment)
    if error is not None:
        return {"ok": False, "error": error}
    return policy(member, payment)

