import renewal, renewal_orig as orig

def call(mod, m, p):
    try:
        return mod.process_renewal(m, p)
    except Exception as e:
        return ('EXC', type(e).__name__)

import itertools, random
methods=['card','transfer','bitcoin',None]
amounts=[-5,0,1,39,40,54,55,56,89,90,100,'x',None]
tiers=['basic','gold','platinum',None,1]
statuses=['active','lapsed','suspended','banned','weird',None]
expired=[0,29,30,31,None,-1,'x']
strikes=[0,1,2,3,4,None,-1,'x']

count=0
for s in statuses:
  for t in tiers:
    for mth in methods:
      for amt in amounts:
        for ex in expired:
          for st in strikes:
            m={'id':'abc','status':s,'tier':t}
            if s!='lapsed': pass
            mm=dict(m)
            p={'amount':amt,'method':mth}
            # include extra member fields meaningfully
            base={'id':'abc','status':s,'tier':t}
            mm=dict(base)
            mm['expired_days']=ex
            mm['strikes']=st
            p=dict(p)
            # also test absent variants
            for omit_member in [False,True]:
              for omit_pay in [False,True]:
                mm2=dict(mm)
                pp=dict(p)
                if omit_member: 
                    k=random.choice(['id','status','tier','expired_days','strikes'])
                    if k in mm2: del mm2[k]
                if omit_pay:
                    k=random.choice(['amount','method'])
                    if k in pp: del pp[k]
                a=call(orig,mm2,pp); b=call(renewal,mm2,pp)
                if a!=b:
                    print('DIFF',repr(mm2),repr(pp),a,b); raise SystemExit(1)
                count+=1

# random fuzz
random.seed(1)
for _ in range(200000):
    mm={'id':random.choice(['x','',123]),'status':random.choice(statuses+['lapsed','suspended','active']),'tier':random.choice(tiers)}
    mm['expired_days']=random.choice(expired)
    mm['strikes']=random.choice(strikes)
    if random.random()<0.1: mm.pop('status',None)
    pp={'amount':random.choice(amounts),'method':random.choice(methods)}
    if random.random()<0.1: pp.pop('amount',None)
    a=call(orig,mm,pp); b=call(renewal,mm,pp)
    if a!=b:
        print('DIFF',repr(mm),repr(pp),a,b); raise SystemExit(1)
    count+=1
print('ALL MATCH', count)
""}

